/// <summary>
/// Extension class for VendInvoiceTrans table to include custom logic for initializing
/// extended comment fields from VendInvoiceInfoLine.
/// </summary>
[ExtensionOf(tableStr(VendInvoiceTrans))]
final class METVendInvoiceTrans_Extension
{

}

Method.Source:
/// <summary>
/// Initializes the VendInvoiceTrans record with extended comment data from the VendInvoiceInfoLine parameter.
/// If MetExtCommentQty is provided, it takes precedence; otherwise, MetExtComment is used.
/// </summary>
/// <param name="_parmLine">The VendInvoiceInfoLine record containing extended comment information.</param>
public void initFromParmLine(VendInvoiceInfoLine _parmLine)
{
    next initFromParmLine(_parmLine);

    ReasonTable  reasonTable = ReasonTable::find(ReasonTableRef::find(this.ReasonTableRef).Reason);

    boolean qtyFailure = reasonTable.METVarianceType == METVarianceType::QuantityVarianceOver || reasonTable.METVarianceType == METVarianceType::QuantityVarianceUnder;
    this.MetExtComment = qtyFailure ? _parmLine.MetExtCommentQty : _parmLine.MetExtComment;
}
